# orch - Alethe Orchestra bridge for agents. Generated by the app; edits are overwritten.
# `orch` runs it from bash (through the sh shim next to it) and from PowerShell (in-process,
# so arguments arrive exactly as typed); cmd uses `orch.cmd`. Text with quotes, & | > % or
# line breaks is safest through --file <path> (UTF-8) or --stdin.
$ErrorActionPreference = 'Stop'
# orch.cmd and the sh shim run this file with `powershell -File`: stdin is then the caller's
# byte stream and the console is this process's. Calls from a PowerShell prompt or script
# have an invocation line and read their pipeline instead.
$standalone = ($env:ALETHE_ORCHESTRA_CLI -eq 'wrapper') -or (-not $MyInvocation.Line)
if ($standalone) {
  try { [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false) } catch { }
}
$endpoint = $env:ALETHE_ORCHESTRA_ENDPOINT
$token = $env:ALETHE_ORCHESTRA_TOKEN
$me = $env:ALETHE_ORCHESTRA_AGENT_ID
# Empty when unset; the app then uses its default session.
$session = [string]$env:ALETHE_ORCHESTRA_SESSION
$statuses = @('thinking', 'editing', 'testing', 'blocked', 'done', 'idle')
$argv = @($args | ForEach-Object { [string]$_ })
$action = ''
if ($argv.Count -gt 0) { $action = $argv[0].ToLowerInvariant() }
$rest = @()
if ($argv.Count -gt 1) { $rest = @($argv[1..($argv.Count - 1)]) }
# Pipeline text of an in-process `--stdin` call, read here at script scope. The automatic
# variable is looked up by name on purpose: a script that names it makes `powershell -File`
# swallow stdin before the script runs, and the wrappers need that stream raw.
$piped = $null
if (-not $standalone -and $MyInvocation.ExpectingInput -and ($argv -contains '--stdin')) {
  $pipeline = Get-Variable -Name ('in' + 'put') -ValueOnly -ErrorAction SilentlyContinue
  $piped = @($pipeline | ForEach-Object { [string]$_ }) -join "`n"
}

function Fail([string]$message) {
  [Console]::Error.WriteLine($message)
  exit 2
}

# Text of raw bytes: a BOM names the encoding; otherwise strict UTF-8, then the ANSI code page
# (what Windows PowerShell's Set-Content writes by default).
function ConvertFrom-Bytes([byte[]]$bytes) {
  if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
    return [Text.Encoding]::UTF8.GetString($bytes, 3, $bytes.Length - 3)
  }
  if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) {
    return [Text.Encoding]::Unicode.GetString($bytes, 2, $bytes.Length - 2)
  }
  if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF) {
    return [Text.Encoding]::BigEndianUnicode.GetString($bytes, 2, $bytes.Length - 2)
  }
  try {
    return (New-Object System.Text.UTF8Encoding($false, $true)).GetString($bytes)
  } catch {
    return [Text.Encoding]::Default.GetString($bytes)
  }
}

# The text of a command: --file <path>, --stdin, or the words typed after the options.
function Read-Text([hashtable]$options, [string[]]$words) {
  if ($options.ContainsKey('file')) {
    $name = [string]$options['file']
    if (-not $name) { Fail 'orch: --file needs a path' }
    $path = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($name)
    if (-not [IO.File]::Exists($path)) { Fail "orch: file not found: $name" }
    return ConvertFrom-Bytes ([IO.File]::ReadAllBytes($path))
  }
  if ($options.ContainsKey('stdin')) {
    if ($standalone) {
      $buffer = New-Object System.IO.MemoryStream
      [Console]::OpenStandardInput().CopyTo($buffer)
      return ConvertFrom-Bytes ($buffer.ToArray())
    }
    if ($null -eq $piped) { Fail 'orch: --stdin needs text piped into orch' }
    return $piped
  }
  return ($words -join ' ')
}

# Leading options of a command. They end at the first word of text (or at `--`), so the text
# may itself contain "--file" or "--after". With -Status a known status word is taken as well.
function Split-Args([string[]]$items, [string[]]$valued, [switch]$Status) {
  $options = @{}
  $i = 0
  while ($i -lt $items.Count) {
    $item = $items[$i]
    $lower = $item.ToLowerInvariant()
    if ($lower -eq '--') { $i++; break }
    if ($lower -eq '--stdin') { $options['stdin'] = $true; $i++; continue }
    if ($lower -match '(?s)^--([a-z]+)(=.*)?$' -and $valued -contains $Matches[1]) {
      $name = $Matches[1]
      if ($Matches[2]) {
        $options[$name] = $item.Substring($name.Length + 3)
        $i++
      } elseif ($i + 1 -lt $items.Count) {
        $options[$name] = $items[$i + 1]
        $i += 2
      } else {
        Fail "orch: --$name needs a value"
      }
      continue
    }
    if ($Status -and -not $options.ContainsKey('status') -and $statuses -contains $lower) {
      $options['status'] = $lower
      $i++
      continue
    }
    break
  }
  $words = @()
  if ($i -lt $items.Count) { $words = @($items[$i..($items.Count - 1)]) }
  return @{ options = $options; words = $words }
}

function Send-Orchestra([string]$path, [hashtable]$body) {
  if (-not $endpoint -or -not $token -or -not $me) {
    Fail 'orch: not running inside an Alethe Orchestra session'
  }
  $body['session'] = $session
  $json = $body | ConvertTo-Json -Compress -Depth 4
  try {
    return Invoke-RestMethod -Uri "$endpoint/orchestra/$path" -Method Post `
      -Headers @{ 'X-Alethe-Token' = $token } `
      -ContentType 'application/json; charset=utf-8' `
      -Body ([Text.Encoding]::UTF8.GetBytes($json))
  } catch {
    $failure = $_
    $detail = [string]$failure.ErrorDetails.Message
    try { $detail = [string](ConvertFrom-Json $detail).error } catch { }
    if (-not $detail) { $detail = $failure.Exception.Message }
    Fail "orch: $detail"
  }
}

# Prints the command's answer; a note on stderr says when the app cut the text to its limit.
function Write-Result([string]$line, $result) {
  if ($result -and $result.clipped) {
    [Console]::Error.WriteLine("orch: the text was cut to $($result.limit) characters")
  }
  $line
}

switch ($action) {
  'report' {
    $usage = 'usage: orch report <0-100> [thinking|editing|testing|blocked|done] [<note> | --file <path> | --stdin]'
    $progress = 0
    if ($rest.Count -lt 1 -or -not [int]::TryParse($rest[0].TrimEnd('%'), [ref]$progress)) { Fail $usage }
    $parsed = Split-Args @($rest | Select-Object -Skip 1) @('file') -Status
    $note = Read-Text $parsed.options $parsed.words
    $status = [string]$parsed.options['status']
    $result = Send-Orchestra 'report' @{ agent_id = $me; progress = $progress; status = $status; note = $note }
    Write-Result 'ok' $result
  }
  'send' {
    $usage = 'usage: orch send <orchestrator|claude-N|all> <message | --file <path> | --stdin>'
    if ($rest.Count -lt 1) { Fail $usage }
    $parsed = Split-Args @($rest | Select-Object -Skip 1) @('file')
    $text = Read-Text $parsed.options $parsed.words
    if (-not $text.Trim()) { Fail $usage }
    $result = Send-Orchestra 'message' @{ from = $me; to = $rest[0]; text = $text }
    Write-Result 'sent' $result
  }
  'spawn' {
    $usage = 'usage: orch spawn <area> [--after claude-N[,claude-M]] [--account ID] [--model M] [--effort E] <task | --file <path> | --stdin>'
    if ($rest.Count -lt 1 -or $rest[0].StartsWith('-')) { Fail $usage }
    $parsed = Split-Args @($rest | Select-Object -Skip 1) @('after', 'account', 'model', 'effort', 'file')
    $task = Read-Text $parsed.options $parsed.words
    if (-not $task.Trim()) { Fail $usage }
    $opts = $parsed.options
    $after = @([string]$opts['after'] -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    $result = Send-Orchestra 'spawn' @{
      from = $me; area = $rest[0]; after = $after; task = $task
      account = [string]$opts['account']; model = [string]$opts['model']; effort = [string]$opts['effort']
    }
    Write-Result ([string]$result.id) $result
  }
  'note' {
    $usage = 'usage: orch note <markdown | --file <path> | --stdin>'
    $parsed = Split-Args $rest @('file')
    $text = Read-Text $parsed.options $parsed.words
    if (-not $text.Trim()) { Fail $usage }
    $result = Send-Orchestra 'note' @{ agent_id = $me; text = $text }
    Write-Result 'noted' $result
  }
  default {
    'orch report <0-100> [thinking|editing|testing|blocked|done] [<note> | --file <path> | --stdin]'
    'orch send <orchestrator|claude-N|all> <message | --file <path> | --stdin>'
    'orch spawn <area> [--after claude-N] [--account ID] [--model M] [--effort E] <task | --file <path> | --stdin>   (orchestrator only)'
    'orch note <markdown | --file <path> | --stdin>   (a decision and its why, for the session record)'
    'Text with quotes, & | > %, or line breaks: write it to a UTF-8 file and pass --file <path>.'
  }
}
